/* ============================================================
   NVC LETTERHEAD — A4 background image (200 DPI PNG, base64).
   Used as: (1) the Word document page background on every page,
   and (2) the on-screen A4 preview sheet background.
   Rendered from 'NVC Letterhead.pdf'. Replace this file to
   change the letterhead everywhere.
   ============================================================ */
(function (NVC) {
  NVC.LETTERHEAD = {
    b64: '',
    get dataUri() { return 'data:image/png;base64,' + this.b64; },
    pxW: 1653, pxH: 2339,        // source pixels (A4 @ ~200 DPI)
  };
})(window.NVC = window.NVC || {});
